{
  "name": "通用蓝牙流式采集设备",
  "name_en": "Generic BLE Streaming Acquisition Device",
  "manufacturer": "",
  "description": "一种通用的蓝牙传感器或采集设备，可连续向实验计算机发送测量数据，并作为 LSL 数据流用于同步记录、在线监测和联合实验。适用于生理信号、运动信号或其他实时传感数据的采集。",
  "description_en": "A generic Bluetooth sensor or acquisition device that continuously sends measurement data to a lab computer and publishes it as an LSL stream for synchronized recording, online monitoring, and multimodal experiments. It is suitable for acquiring biosignals, motion signals, or other real-time sensor data.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "开始通过 LSL 输出口进行数据流传输。",
      "description_en": "Start streaming data through the LSL outlet."
    },
    {
      "action_name": "auto-stop",
      "description": "停止或暂停通过 LSL 输出口进行的数据流传输。",
      "description_en": "Stop or pause streaming through the LSL outlet."
    },
    {
      "action_name": "auto-subscriptions",
      "description": "获取已订阅的数据流名称。",
      "description_en": "Get the names of the subscribed streams."
    },
    {
      "action_name": "auto-send_command",
      "description": "向已连接设备发送命令。",
      "description_en": "Send a command to the connected device."
    },
    {
      "action_name": "auto-backend",
      "description": "获取/设置/定义通信后端。",
      "description_en": "Get/set/define the communication backend."
    },
    {
      "action_name": "auto-address",
      "description": "获取/设置/定义设备地址。",
      "description_en": "Get/set/define the device address."
    },
    {
      "action_name": "auto-make_chunk",
      "description": "生成一段用于流传输的数据块。",
      "description_en": "Generate a chunk of data for streaming."
    }
  ],
  "tag_hints": [
    "BLE sensing",
    "LSL streaming",
    "real-time data acquisition",
    "wearable biosignals",
    "multimodal experiment synchronization",
    "sensor data streaming"
  ]
}

